from datetime import datetime, timedelta


class Scheduler:
    def __init__(self) -> None:
        self._appointments = {}
        self._next_id = 1

    def book(self, patient: str, doctor: str, start: datetime, end: datetime,
             now: datetime) -> int:
        if start < now:
            raise ValueError("Cannot book an appointment in the past.")
        if not self.is_free(doctor, start, end):
            raise ValueError("The doctor is not free during this time slot.")

        appointment_id = self._next_id
        self._next_id += 1
        self._appointments[appointment_id] = {
            "patient": patient,
            "doctor": doctor,
            "start": start,
            "end": end,
            "cancelled": False,
            "blocked": True,
        }
        return appointment_id

    def cancel(self, appointment_id: int, now: datetime) -> None:
        appointment = self._appointments.get(appointment_id)
        if appointment is None:
            raise ValueError("Unknown appointment id.")
        if appointment["cancelled"]:
            return
        if appointment["start"] - now < timedelta(hours=24):
            # Too close to start: slot stays blocked.
            appointment["cancelled"] = True
            appointment["blocked"] = True
        else:
            appointment["cancelled"] = True
            appointment["blocked"] = False

    def is_free(self, doctor: str, start: datetime, end: datetime) -> bool:
        for appointment in self._appointments.values():
            if appointment["doctor"] != doctor:
                continue
            if not appointment["blocked"]:
                continue
            if start < appointment["end"] and appointment["start"] < end:
                return False
        return True
